globalThis.photoDistance=function(a,b){const rad=Math.PI/180,dlat=(b.latitude-a.latitude)*rad,dlon=(b.longitude-a.longitude)*rad;const h=Math.sin(dlat/2)**2+Math.cos(a.latitude*rad)*Math.cos(b.latitude*rad)*Math.sin(dlon/2)**2;return 6371000*2*Math.asin(Math.sqrt(Math.min(1,h)));};
globalThis.groupPhotos=function(photos,radius=15){
 if(!Number.isFinite(radius)||radius<0||radius>10000)throw Error('Distanța de grupare trebuie să fie între 0 și 10000 m.');
 const groups=[],valid=p=>Number.isFinite(p.latitude)&&Math.abs(p.latitude)<=90&&Number.isFinite(p.longitude)&&Math.abs(p.longitude)<=180;
 for(const p of photos){let group=valid(p)?groups.find(g=>valid(g[0])&&photoDistance(g[0],p)<=radius):null;if(!group){group=[];groups.push(group);}group.push(p);}return groups;
};
TTI.setupBatchPhotos=function(upload,button,controls){
 upload.multiple=true;button.textContent='＋ Puncte din fotografii';let photos=[],groups=[],saved=[],generation=0,radius=15;
 const preview=(file)=>{const img=el('img'),url=URL.createObjectURL(file);img.src=url;img.alt=file.name;img.style.cssText='width:100%;max-height:150px;object-fit:contain';img.onload=img.onerror=()=>URL.revokeObjectURL(url);return img;};
 const regroup=()=>{groups=groupPhotos(photos.filter(p=>!p.saved),radius).map(items=>{const s=controls.make(items[0].file);s.files=items;s.batch=true;s.latitude=items[0].latitude;s.longitude=items[0].longitude;s.address=items.find(p=>p.address)?.address||'';s.source=items.length+' fotografii în grup. Rază de maximum '+radius+' m față de prima fotografie cu coordonate. Verifică poziția și alege stratul.';s.back=showBatch;s.onSaved=()=>{items.forEach(p=>p.saved=true);saved.push(s);groups=groups.filter(g=>g!==s);showBatch();};return s;});};
 function showBatch(){
  controls.begin();selected=null;$('details').hidden=false;const content=$('detail-content');content.replaceChildren(el('h2','Puncte din fotografii','detail-title'));
  const box=el('section',undefined,'point-editor'),msg=el('p',`${photos.length} fotografii · ${groups.length} grupuri de salvat · ${saved.length} puncte salvate`,'save-status');msg.setAttribute('role','status');box.append(msg,el('p','Distanța aplicată: '+radius+' m față de prima fotografie a grupului. Cele fără poziție rămân separate.'));
  const locked=groups.some(g=>g.created);if(locked)box.append(el('p','Finalizează atașarea fotografiilor la punctul deja creat înainte de regrupare.'));
  const radiusLabel=el('label','Distanța de grupare (m)'),distance=el('input');distance.type='number';distance.min='0';distance.max='10000';distance.step='any';distance.required=true;distance.value=String(radius);distance.disabled=locked;radiusLabel.append(distance);const apply=el('button','Aplică distanța');apply.disabled=locked;apply.onclick=()=>{if(TTI.busy||locked||!distance.reportValidity())return;radius=Number(distance.value);regroup();showBatch();};box.append(radiusLabel,apply,el('small','0 m grupează doar fotografiile cu aceleași coordonate. Modificarea se aplică doar fotografiilor încă nesalvate.'));
  const read=el('button','Citește cu AI fotografiile fără coordonate');read.disabled=locked||!photos.some(p=>!p.saved&&p.latitude===null);box.append(el('p','La apăsare, fotografiile fără coordonate sunt trimise către OpenAI, pe rând.'),read);
  read.onclick=async()=>{if(TTI.busy||locked)return;TTI.busy=true;read.disabled=true;const token=generation;let stopped=false;const stop=el('button','Oprește citirea după fotografia curentă');stop.onclick=()=>{stopped=true;stop.disabled=true;};box.prepend(stop);const pending=photos.filter(p=>!p.saved&&p.latitude===null);try{for(let i=0;i<pending.length;i++){if(token!==generation||stopped)break;const p=pending[i];msg.textContent=`Citire AI ${i+1}/${pending.length}: ${p.file.name}`;try{const r=await TTI.request('/photo-location',{method:'POST',headers:{'Content-Type':p.file.type||'application/octet-stream'},body:p.file});if(token!==generation)break;Object.assign(p,{latitude:r.latitude,longitude:r.longitude,address:r.address,note:[r.confidence==='low'?'Citire nesigură — verifică atent.':'',r.warning,r.stamp].filter(Boolean).join(' ')});}catch(e){p.note=e.message;}}if(token===generation){regroup();showBatch();}}finally{TTI.busy=false;read.disabled=false;}};
  const details=el('details'),summary=el('summary','Verifică sau corectează coordonatele fotografiilor');details.append(summary);box.append(details);
  for(const p of photos.filter(p=>!p.saved)){const row=el('article',undefined,'observation');row.append(preview(p.file),el('strong',p.file.name));if(p.note)row.append(el('p',p.note));for(const [key,label,max] of [['latitude','Latitudine',90],['longitude','Longitudine',180]]){const wrap=el('label',label+' · '+p.file.name),input=el('input');input.value=p[key]??'';input.inputMode='decimal';input.disabled=locked;input.onchange=()=>{const text=input.value.trim().replace(',','.');const n=text===''?null:Number(text);p[key]=Number.isFinite(n)&&Math.abs(n)<=max?n:null;input.value=p[key]??'';};wrap.append(input);row.append(wrap);}details.append(row);}
  const recalc=el('button','Regrupează după coordonate');recalc.disabled=locked;recalc.onclick=()=>{if(TTI.busy||locked)return;regroup();showBatch();};details.append(recalc);
  groups.forEach((s,i)=>{const row=el('article',undefined,'observation');row.append(el('strong',`Grup ${i+1} · ${s.files.length} fotografii`),el('p',s.files.map(p=>p.file.name).join(', ')),el('p',(s.latitude===null||s.longitude===null)?'Fără poziție — alege pe hartă la verificare.':`${s.latitude.toFixed(6)}, ${s.longitude.toFixed(6)}`));const open=el('button',s.created?'Reîncearcă fotografiile':'Verifică și salvează grupul '+(i+1));open.onclick=()=>{if(!TTI.busy)controls.open(s);};row.append(open);box.append(row);});
  for(const s of saved){const row=el('article',undefined,'observation');row.append(el('strong','Salvat · '+s.files.length+' fotografii'),el('p',s.name||s.files[0].file.name));box.append(row);}
  const close=el('button','Închide');close.onclick=()=>{if(TTI.busy)return;controls.begin();$('details').hidden=true;};box.append(close);content.append(box);$('details').scrollTop=0;
 }
 upload.onchange=async()=>{if(TTI.busy)return;const files=[...upload.files];if(!files.length)return;if(files.length>100||files.reduce((n,f)=>n+f.size,0)>200*1024*1024||files.some(f=>!f.size||f.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type))){alert('Selectează maximum 100 fotografii JPEG, PNG sau WebP, de cel mult 10 MB fiecare și 200 MB în total.');return;}generation++;const token=generation;TTI.cancelCableSelection();controls.begin();photos=[];groups=[];saved=[];TTI.busy=true;try{for(const file of files){let gps=null;try{gps=photoGPS(await file.arrayBuffer());}catch{}photos.push({file,photoId:crypto.randomUUID(),latitude:gps?.latitude??null,longitude:gps?.longitude??null,note:gps?'Coordonate EXIF citite local.':'Fără coordonate EXIF.',uploaded:false,saved:false});}if(token===generation){regroup();showBatch();}}finally{TTI.busy=false;}};
};
